  kid_friendly, technical, surface, fee, permit) VALUES ('mount-timpanogos-aspen-grove', 'utah-county', 'Mount Timpanogos via Aspen Grove', 'Provo Canyon / Alpine Loop', 'Steeper and more dramatic than Timpooneke, this route passes a string of waterfalls and Emerald Lake below the Timp glacier before topping out on the summit.', 'Snowfields linger near Emerald Lake well into summer — microspikes are helpful early season.', 40.4048, -111.605, 13.8, 4900, 11752, 'out-and-back', 10, 'Strenuous', 423, '["summit","views","waterfall","lake","wildflowers","wildlife"]', '["hike","trail-run"]', '["summer","fall"]', 'leash', 0, 1, 'dirt / talus', 'Alpine Loop recreation fee', NULL)
